import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';
import { ensureBoard, mintInvite, openSecondMember } from './retro-helpers';

test.describe(`team member: add a card to 'went well,' 'to improve,' or 'action items'`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a member adds a card to any column, every other member sees it in that column within 5s`, async ({ page, browser }) => {
    await ensureBoard(page);
    const code = await mintInvite(page);
    const { ctx: ctxB, page: pageB } = await openSecondMember(browser, code, 1);

    // Member A adds a card to the "Went well" column.
    const text = 'Shipped on time';
    await page.getByPlaceholder('Add to went well…').fill(text);
    await page.getByRole('button', { name: 'Add card' }).first().click();

    // Every other member sees that card in the column.
    await expect(pageB.getByText(text)).toBeVisible({ timeout: 15_000 });

    await ctxB.close();
  });
});
